export const DEFECTS_BY_ID = Object.fromEntries(DEFECTS.map((d) => [d.id, d]));

export function defectsFor(sectionId, severity) {
  return DEFECTS.filter((d) => d.section === sectionId && (!severity || d.sev === severity));
}

export function sectionsWithDefects(severity) {
  const ids = new Set(DEFECTS.filter((d) => !severity || d.sev === severity).map((d) => d.section));
  return ids;
}
